'use strict';

// MODULES //

var BigInt = require( '@stdlib/bigint/ctor' );
var Number = require( '@stdlib/number/ctor' );
var ToPrimitiveSymbol = require( '@stdlib/symbol/to-primitive' );
var Uint32Array = require( '@stdlib/array/uint32' );
var format = require( '@stdlib/string/format' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var hasToPrimitiveSymbolSupport = require( '@stdlib/assert/has-to-primitive-symbol-support' ); // eslint-disable-line id-length
var isArray = require( '@stdlib/assert/is-array' );
var isBigInt = require( '@stdlib/assert/is-bigint' );
var isNan = require( '@stdlib/assert/is-nan' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isString = require( '@stdlib/assert/is-string' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var max = require( '@stdlib/math/base/special/max' );
var setEnumerableReadOnly = require( '@stdlib/utils/define-read-only-property' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var trim = require( '@stdlib/string/trim' );
var asBigUint64 = require( './asbiguint64.js' );
var toStr = require( './tostring.js' );
var toJSON = require( './tojson.js' );
var valueOf = require( './valueof.js' ); // eslint-disable-line stdlib/no-redeclare

// TODO: should we add asm type annotations aggressively?
var MAX_UINT32 = 0xffffffff;
var TWO_32 = 0x100000000;


// MAIN //

/**
* Unsigned 64-bit integer constructor.
*
* @constructor
* @param {number|string|Array<number>|Uint32Array|BigInt} value - numeric value or high low words or BigInt
* TODO: Which ones should we keep and discard? Should we support any arraylike argument?
* @param {boolean} useHighLow - use double word Uint32Array representation
* @throws {TypeError} must invoke using the `new` keyword
* @throws {TypeError} value must be a number or bla bla bla // TODO: update after review
* @returns {Uint64} Unsigned 64-bit integer
*
* @example // TODO: add more example
* var x = new Uint64( 5 );
* // returns <Uint64>
*/
function Uint64( value, useHighLow ) {
	// TODO: should we optimize number of vars?
	var high;
	var low;
	var tmp;
	var ih;
	var il;
	var i;

	useHighLow |= !hasBigIntSupport();

	if ( !( this instanceof Uint64 ) ) {
		throw new TypeError( 'invalid invocation. Constructor must be called with the `new` keyword.' );
	}

	// TODO: current implementation uses either BigInt or Uint32Array for the internal representation
	// Are there other better alternative instead of Uint32Array? How is plain old number array?
	// Or an object with properties named high, low and big
	// - where high low is always present and big is the bigint representation when applicable

	if ( isBigInt( value ) ) {
		value = asBigUint64( value );
		if ( useHighLow ) {
			high = Number( value >> BigInt( 32 ) );
			low = Number( value & BigInt( MAX_UINT32 ) );
			value = new Uint32Array( [ high, low ] );

			// TODO: should we use value[0] = high, value[1] = low instead to avoid the intermediate [high, low] array allocation?
		}
	}
	else if ( isUint32Array( value ) ) {
		if ( value.length === 2 ) {
			if ( !useHighLow ) {
				value = ( BigInt( value[ 0 ] ) << BigInt( 32 ) ) | BigInt( value[ 1 ] );
			}
		}
		else {
			throw new TypeError( format( 'invalid argument. Provided Uint32Array must have a length of 2. Value: `%s`.', value ) );
		}
	}
	else if ( isArray( value ) ) {
		if ( value.length === 2 ) {
			if ( typeof value[ 0 ] === 'number' && typeof value[ 1 ] === 'number' ) {
				if ( value[ 0 ] >= 0 && value[ 0 ] <= MAX_UINT32 && value[ 1 ] >= 0 && value[ 1 ] <= MAX_UINT32 ) {
					value[ 0 ] >>>= 0;
					value[ 1 ] >>>= 0;
					if ( useHighLow ) {
						value = new Uint32Array( value );
					}
					else {
						value = ( BigInt( value[ 0 ] ) << BigInt( 32 ) ) | BigInt( value[ 1 ] );
					}
				}
				else {
					throw new TypeError( format( 'invalid argument. Provided numbers must be between 0 and %s. Value: `%s`.', MAX_UINT32, value ) );
				}
			}
			else {
				throw new TypeError( format( 'invalid argument. Provided array must contain only elements of type number. Value: `%s`.', value ) );
			}
		}
		else {
			throw new TypeError( format( 'invalid argument. Provided array must have a length of 2. Value: `%s`.', value ) );
		}
	}
	else if ( isString( value ) ) {
		// TODO: verify same parsing behavior as BigInt
		if ( useHighLow ) {
			value = trim( value );
			if ( value.match( /^0x/i ) ) {
				il = max( 2, value.length - 8 );
				ih = max( 2, value.length - 16 );
				high = Number( '0x' + value.slice( ih, il ) );
				low = Number( '0x' + value.slice( il ) );
			}
			else if ( value.match( /^0o/i ) ) {
				il = max( 2, value.length - 16 );
				ih = max( 2, value.length - 32 );
				high = Number( '0o' + value.slice( ih, il ) );
				low = Number( '0o' + value.slice( il ) );
			}
			else if ( value.match( /^0b/i ) ) {
				il = max( 2, value.length - 32 );
				ih = max( 2, value.length - 64 );
				high = Number( '0b' + value.slice( ih, il ) );
				low = Number( '0b' + value.slice( il ) );
			}
			else if ( value.match( /[^0-9]/ ) ) {
				high = low = NaN;
			}
			else {
				// chunked parsing for decimal string
				i = ( value.length % 6 ) || 6; // processes the first chunk such as the remaining chunks are all evenly sized (6digit)
				if ( i + 6 <= 9 ) { // takes big chunk when possible
					i += 6;
				}
				high = 0;
				low = Number( value.slice( 0, i ) );
				for ( ; i < value.length; i += 6 ) {
					tmp = Number( value.slice( i, i + 6 ) );
					low = ( low * 1e6 ) + tmp;
					tmp = ( low / TWO_32 ) >>> 0;
					low -= tmp * TWO_32;
					high = ( high * 1e6 ) + tmp;
					tmp = ( high / TWO_32 ) >>> 0;
					high -= tmp * TWO_32;
				}
			}

			if ( !isNaN( high ) && !isNan( low ) ) {
				value = new Uint32Array( [ high, low ] );
			}
			else {
				throw new TypeError( format( 'invalid argument. Could not convert string to Uint64. Value: `%s`.', value ) );
			}
		}
		else {
			try {
				value = asBigUint64( BigInt( value ) );
			}
			// eslint-disable-next-line no-unused-vars
			catch ( error ) {
				throw new TypeError( format( 'invalid argument. Could not convert string to Uint64. Value: `%s`.', value ) );
			}
		}
	}
	else if ( isNumber( value ) ) {
		if ( value >= 0 && Number.isSafeInteger( value ) ) {
			if ( useHighLow ) {
				high = ( value / TWO_32 ) >>> 0;
				low = value >>> 0;
				value = new Uint32Array( [ high, low ] );
			}
			else {
				value = asBigUint64( BigInt( value ) );
			}
		}
		else {
			throw new TypeError( format( 'invalid argument. Provided number must be between 0 and %s. Value: `%s`.', Number.MAX_SAFE_INTEGER, value ) );
		}
	}
	else {
		throw new TypeError( format( 'invalid argument. Must provide a number or string or Array<number> or Uint32Array or BigInt. Value: `%s`.', value ) );
	}

	// TODO: make the `value` property / whatever internal representation private
	// I guess it's not technically possible to make it truely private in our implementation because of the current of structure of the package?
	// using es6 class is not permitted and the other option is closure based encapsulation but then we'll have to move the other member functions inside the constructor
	setEnumerableReadOnly( this, 'value', value );
	return this;
}

/**
* Constructor name.
*
* @name name
* @memberof Uint64
* @readonly
* @type {string}
* @default 'Uint64'
*
* @example
* var name = Uint64.name;
* // returns 'Uint64'
*/
setReadOnly( Uint64, 'name', 'Uint64' );

/**
* Size (in bytes) of the underlying value.
*
* @name BYTES_PER_ELEMENT
* @memberof Uint64
* @type {integer}
* @returns {integer} size in bytes
*
* @example
* var nbytes = Uint64.BYTES_PER_ELEMENT;
* // returns 8
*/
setReadOnly( Uint64, 'BYTES_PER_ELEMENT', 8 );

/**
* Size (in bytes) of the underlying value.
*
* @name BYTES_PER_ELEMENT
* @memberof Uint64.prototype
* @type {integer}
* @returns {integer} size in bytes
*
* @example
* var x = new Uint64( 5 );
*
* var nbytes = x.BYTES_PER_ELEMENT;
* // returns 8
*/
setReadOnly( Uint64.prototype, 'BYTES_PER_ELEMENT', 8 );

/**
* Serializes an unsigned 64-bit integer number as a string.
*
* @name toString
* @memberof Uint64.prototype
* @type {Function}
* @returns {string} serialized unsigned 64-bit integer number
*
* @example
* var str = new Uint64( 5 ).toString();
* // returns '5'
*
* str = new Uint64( [ 1, 0 ] ).toString();
* // returns '4294967296'
*
* str = new Uint64( 100000000001 ).toString();
* // returns '100000000001'
*
*/
setReadOnly( Uint64.prototype, 'toString', toStr );

/**
* Serializes an unsigned 64-bit integer number as a JSON object.
*
* ## Notes
*
* -   `JSON.stringify()` implicitly calls this method when stringifying a `Uint64` instance.
*
* @name toJSON
* @memberof Uint64.prototype
* @type {Function}
* @returns {Object} serialized unsigned 64-bit integer number
*
* @example
* var x = new Uint64( 5 );
*
* var obj = x.toJSON();
* // returns { 'type': 'Uint64', 'value': '5' }
*/
setReadOnly( Uint64.prototype, 'toJSON', toJSON );

/**
* Converts an unsigned 64-bit integer number to a primitive value.
*
* @name valueOf
* @memberof Uint64.prototype
* @type {Function}
* @returns {number} primitive value
*
* @example
* var x = new Uint64( 5 );
*
* var v = x.valueOf();
* // returns 5.0
*/
setReadOnly( Uint64.prototype, 'valueOf', valueOf );

/**
* Returns the primitive value of an unsigned 64-bit integer number.
*
* @name toPrimitive
* @memberof Uint64.prototype
* @type {Function}
* @param {string} hint - conversion hint
* @returns {number} primitive value
*
* @example
* var hasSymbol = require( '@stdlib/assert/has-to-primitive-symbol-support' );
* var ToPrimitiveSymbol = require( '@stdlib/symbol/to-primitive' );
*
* var x = new Uint64( 5 );
*
* var v;
* if ( hasSymbol() ) {
*     v = x[ ToPrimitiveSymbol ]( 'number' );
*     // returns 5.0
* }
*/
if ( hasToPrimitiveSymbolSupport() ) {
	setReadOnly( Uint64.prototype, ToPrimitiveSymbol, valueOf );
}


// EXPORTS //

module.exports = Uint64;
